# ==========================================
# 1. DATABASE INITIALIZATION & SEEDING
# ==========================================
def init_db():
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()

    # Create Tables
    cur.execute("CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY, title TEXT, requirement TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS candidates (id INTEGER PRIMARY KEY, username TEXT, name TEXT, qualification TEXT, experience TEXT, job_id INTEGER, status TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY, subject TEXT, question TEXT, op1 TEXT, op2 TEXT, op3 TEXT, op4 TEXT, answer TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS results (id INTEGER PRIMARY KEY, username TEXT, subject TEXT, score INTEGER, salary INTEGER, status TEXT)")
    cur.execute("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password TEXT, role TEXT)")

    # Seed Default Admin Account
    cur.execute("SELECT * FROM users WHERE username='admin'")
    if not cur.fetchone():
        hashed_password = generate_password_hash("admin123")
        cur.execute("INSERT INTO users (username, password, role) VALUES (?, ?, ?)", ("admin", hashed_password, "admin"))

    conn.commit()
    conn.close()

