# 3. AUTHENTICATION ROUTES
# ==========================================
@app.route("/", methods=["GET", "POST"])
def login():
    error = None
    if request.method == "POST":
        username = request.form["username"]
        password = request.form["password"]

        conn = sqlite3.connect("database.db")
        cur = conn.cursor()
        cur.execute("SELECT password, role FROM users WHERE username=?", (username,))
        user_record = cur.fetchone()
        conn.close()

        if user_record and check_password_hash(user_record[0], password):
            session["user"] = username
            session["role"] = user_record[1]
            
            if session["role"] == "admin":
                return redirect("/dashboard")
            else:
                return redirect("/jobs")
        else:
            error = "Invalid username or password. Please try again."
            
    return render_template("login.html", error=error)

@app.route("/register", methods=["GET", "POST"])
def register():
    error = None
    success = None
    if request.method == "POST":
        # Using .get() prevents the "KeyError" crash
        username = request.form.get("username")
        password = request.form.get("password")
        confirm_password = request.form.get("confirm_password") # Changed from [] to .get()

        if not username or not password or not confirm_password:
            error = "All fields are required!"
            return render_template("register.html", error=error)

        if password != confirm_password:
            error = "Passwords do not match!"
            return render_template("register.html", error=error)
            
        # ... rest of your database logic ...
        conn = sqlite3.connect("database.db")
        cur = conn.cursor()

        cur.execute("SELECT * FROM users WHERE username=?", (username,))
        if cur.fetchone():
            error = "Username already exists. Please choose another."
        else:
            hashed_password = generate_password_hash(password)
            cur.execute("INSERT INTO users (username, password, role) VALUES (?, ?, ?)", (username, hashed_password, "candidate"))
            conn.commit()
            success = "Registration successful! You can now log in."
        
        conn.close()

        if success:
            return render_template("login.html", success=success)

    return render_template("register.html", error=error)

@app.route("/logout")
def logout():
    session.clear()
    return redirect("/")

