@app.route("/dashboard")
@admin_required
def dashboard():
    conn = sqlite3.connect("database.db")
    conn.row_factory = sqlite3.Row  # This is critical for template compatibility
    cur = conn.cursor()

    # Get General Stats
    cur.execute("SELECT COUNT(*) FROM candidates")
    total = cur.fetchone()[0]
    cur.execute("SELECT COUNT(*) FROM results WHERE status='Selected'")
    selected = cur.fetchone()[0]
    cur.execute("SELECT SUM(salary) FROM results")
    salary = cur.fetchone()[0] or 0

    # Fetch all jobs to list them on the dashboard
    cur.execute("""
        SELECT jobs.id, jobs.title, COUNT(candidates.id) as app_count 
        FROM jobs 
        LEFT JOIN candidates ON jobs.id = candidates.job_id 
        GROUP BY jobs.id
    """)
    jobs_list = cur.fetchall()

    conn.close()
    return render_template("dashboard.html", total=total, selected=selected, salary=salary, jobs_list=jobs_list)

@app.route("/add_job", methods=["GET", "POST"])
@admin_required
def add_job():
    if request.method == "POST":
        conn = sqlite3.connect("database.db")
        cur = conn.cursor()
        cur.execute("INSERT INTO jobs (title, requirement) VALUES (?, ?)", 
                    (request.form["title"], request.form["requirement"]))
        conn.commit()
        conn.close()
        return redirect("/dashboard") # Redirect to dashboard after adding
    return render_template("add_job.html")

@app.route("/candidates/<int:job_id>")
@admin_required
def candidates(job_id):
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()
    cur.execute("SELECT * FROM candidates WHERE job_id=?", (job_id,))
    data = cur.fetchall()
    conn.close()
