@app.route("/update_status/<int:candidate_id>/<string:new_status>")
@admin_required
def update_status(candidate_id, new_status):
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()
    cur.execute("UPDATE candidates SET status=? WHERE id=?", (new_status, candidate_id))
    conn.commit()
    conn.close()
    return redirect(request.referrer)

@app.route("/jobs")
def jobs():
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()
    cur.execute("SELECT * FROM jobs")
    all_jobs = cur.fetchall()
    
    user_status = {}
    if "user" in session:
        cur.execute("SELECT job_id, status FROM candidates WHERE username=?", (session["user"],))
        rows = cur.fetchall()
        user_status = {row[0]: row[1] for row in rows}
    
    conn.close()
    return render_template("index.html", jobs=all_jobs, user_status=user_status)

