@app.route("/apply/<int:job_id>", methods=["GET", "POST"])
@login_required
def apply(job_id):
    if request.method == "POST":
        username = session["user"] 
        conn = sqlite3.connect("database.db")
        cur = conn.cursor()
        
        # We set the initial status to 'Pending Review'
        # This exact string is what the admin template looks for
        cur.execute("""
            INSERT INTO candidates (username, name, qualification, experience, job_id, status) 
            VALUES (?, ?, ?, ?, ?, ?)
        """, (username, request.form["name"], request.form["qualification"], 
              request.form["experience"], job_id, "Pending Review"))
        
        conn.commit()
        conn.close()
        return redirect("/my_status")
    return render_template("apply.html", job_id=job_id)

@app.route("/my_status")
@login_required
def my_status():
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()
    # Ensure jobs.title is first (app[0]) and candidates.status is second (app[1])
    cur.execute("""
        SELECT jobs.title, candidates.status 
        FROM candidates 
        JOIN jobs ON candidates.job_id = jobs.id 
        WHERE candidates.username = ?
    """, (session["user"],))
    applications = cur.fetchall()
    conn.close()
    return render_template("my_status.html", applications=applications)

@app.route("/test/<subject>", methods=["GET", "POST"])
@login_required
def test(subject):
    conn = sqlite3.connect("database.db")
    cur = conn.cursor()

    if request.method == "POST":
        # 1. Initialize variables HERE so they are never "unbound"
        score = 0
        status = "Rejected"
        salary = 0
        
        cur.execute("SELECT * FROM questions WHERE subject=?", (subject,))
        qs = cur.fetchall()

        # 2. Calculate score
        for q in qs:
            # Check if user answered this question
            user_answer = request.form.get(str(q[0]))
            if user_answer == q[7]: # q[7] is the correct answer index
                score += 1

        # 3. Determine Status and Salary based on score
        if score >= 35:
            status, salary = "Selected", 60000
        elif score >= 25:
            status, salary = "Selected", 45000
        elif score >= 15:
            status, salary = "Selected", 30000
        else:
            status, salary = "Rejected", 0

        # 4. Save results to database
        cur.execute("INSERT INTO results (username, subject, score, salary, status) VALUES (?,?,?,?,?)",
                    (session["user"], subject, score, salary, status))
        
        # 5. Update the candidate's application status
        cur.execute("UPDATE candidates SET status=? WHERE username=? AND job_id IN (SELECT id FROM jobs WHERE title=?)", 
                    (status, session["user"], subject))

        conn.commit()
        conn.close()

        # 6. Pass the variables to result.html
        return render_template("result.html", score=score, status=status, salary=salary)
    
    # GET Logic: Fetch questions to display
    cur.execute("SELECT * FROM questions WHERE subject=? ORDER BY RANDOM() LIMIT 40", (subject,))
    qs = cur.fetchall()
    conn.close()
    
    if not qs:
        return "Error: No questions found for this subject. Please check admin job titles."
        
    return render_template("test.html", questions=qs, subject=subject)

